## System call tracing

```c
// proc.h
struct proc {
  int mask; //for tracing
};

```

```c
// syscall.c
const char *syscall_names[] = {
"placeholder", "fork", "exit", "wait", "pipe", "read", "kill", "exec", "fstat", "chdir",
"dup", "getpid", "sbrk", "sleep", "uptime", "open", "write", "mknod",
"unlink", "link", "mkdir", "close", "trace", "sysinfo",
};

void
syscall(void)
{
  int num;
  struct proc *p = myproc();

  num = p->trapframe->a7;
  if(num > 0 && num < NELEM(syscalls) && syscalls[num]) {
    p->trapframe->a0 = syscalls[num]();
      if ((p->mask >> num) & 1)
          printf("%d: syscall %s -> %d\n", p->pid, syscall_names[num], p->trapframe->a0);
  } else {
    printf("%d %s: unknown sys call %d\n",
            p->pid, p->name, num);
    p->trapframe->a0 = -1;
  }
}
```

```c
// kernel/proc.c
int
fork(void)
{
// ...
  np->mask = p->mask; // copy mask from parent to child
// ...
}
```

```c
// sysproc.c
uint64 sys_trace(void)
{
    int mask;
    if(argint(0, &mask) < 0)
        return -1;

    struct proc *p = myproc();
    p->mask |= mask;
    return 0;
}
```

