## Sysinfo

```c
// proc.c
uint64 countproc(void)
{
  struct proc *p;
  int count = 0;
  for(p = proc; p < &proc[NPROC]; p++){
        if (p->state != UNUSED)
            count++;
  }
  return count;
}
```

```c
// kalloc.c
uint64 kfreemem(void)
{
    struct run *r;

    uint64 total = 0; 
    acquire(&kmem.lock);
    for (r = kmem.freelist; r; r = r->next)
        total += PGSIZE;
    release(&kmem.lock);
    return total;
}
```

```c
// sysproc.c
uint64 sys_sysinfo(void)
{
  struct sysinfo info;
  uint64 addr;

  if (argaddr(0, &addr) < 0)
        return -1;

  info.freemem = kfreemem();
  info.nproc = countproc();

  struct proc *p = myproc();
  if(copyout(p->pagetable, addr, (char *)&info, sizeof(info)) < 0)
      return -1;

    return 0;
}

```

