## primes
网站上给的论文[Bell Labs and CSP Threads](https://swtch.com/~rsc/thread/)很好得说明了原理。
我先没有用fork，只用pipe模拟了这个sieve。因为无法确定终止的循环数，而且网站上提示用递归，所以用迭代做这题是合理的。
```c
#include "kernel/types.h"
#include "kernel/stat.h"
#include "user/user.h"

void sieve(int read_fd) 
{
    int p;
    char buf[1];

    if (read(read_fd, buf, 1) == 0) {
        close(read_fd);
        exit(0);
    }

    p = buf[0];
    printf("prime %d\n", p);

    int fds[2];
    pipe(fds);
    if (fork() == 0) {
        close(fds[1]);
        sieve(fds[0]);
        exit(0);
    } else {
        close(fds[0]);
        while (read(read_fd, buf, 1)) {
            if (buf[0] % p != 0) {
                write(fds[1], buf, 1);
            }
        }
    }

    close(read_fd);
    close(fds[1]);
    wait(0);
    exit(0);
}

int main(int argc, char *argv[])
{
    int fds[2];
