## xargs
我之前都没有用过这个命令，看[这篇文章](https://ruanyifeng.com/blog/2019/08/xargs-tutorial.html)了解了它的功能，感觉挺好用的。

这里的思路简单，就是先把argv和管道运算符 `|` 传来的参数放在一个数组里，再用`fork`和`exec`执行。
前面的处理有几点要注意：
- `|`传来的参数要从`0` 描述符里读取；
- 新数组要排除`argv[0]`，不然可能递归调用`xargs`；
- 从示例可知，`xargs`之后的参数要与前面的每一行拼接运行。

没有写 -n 参数，评分系统也过了，不过要写也能写。
```c
#include "kernel/param.h"
#include "kernel/types.h"
#include "kernel/stat.h"
#include "user/user.h"

char* readline() 
{
    char* buf = malloc(100);
    if (!buf) {
        return 0;
    }

    char* p = buf;
    while (read(0, p, 1) == 1) {
        if (*p == '\n' || *p == 0) {
            *p = 0;
            return buf;
        }
        p++;
    }

    if (p != buf) {
        *p = 0;
        return buf;
    }

    free(buf);
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        printf("Usage: xargs command");
        exit(1);
    }

    char* arr[MAXARG];
    char* line;

    while ((line = readline()) != 0) {
        int arr_index = 0;
        for (int i = 1; i < argc; i++) {
            arr[arr_index++] = argv[i];
        }

        char* p = line;
        while (*p) {
            while (*p == ' ') p++;
            if (*p == 0) break;

            char* start = p;
            while (*p && *p != ' ') p++;
            int len = p - start;
            char* arg = malloc(len + 1);
            if (!arg) {
                printf("malloc failed\n");
                exit(1);
            }

            for (int i = 0; i < len; i++) {
                arg[i] = start[i];
            }
            arg[len] = 0;

            arr[arr_index++] = arg;
            if (arr_index >= MAXARG - 1) break;
        }
        arr[arr_index] = 0;

        int pid = fork();
        if (pid == 0) {
            exec(arr[0], arr);
            printf("exec failed!\n");
            exit(1);
        } else {
            wait((int *)0);
        }

        for (int i = argc - 1; i < arr_index; i++) {
            free(arr[i]);
        }
        free(line);
    }

    exit(0);
}
```

